type Listener<T = unknown> = {
  callback: (...args: T[]) => unknown;
  once: boolean;
};

type EventType = {
  [key: string]: Listener[];
};

export function createEventEmitter() {
  const events: EventType = {};

  function on<T = unknown>(
    event: string,
    callback: (...args: T[]) => unknown,
    once = false
  ) {
    if (!events[event]) {
      events[event] = [];
    }
    events[event].push({ callback, once });
    return this;
  }

  function off(event: string, callback: (...args: unknown[]) => unknown) {
    if (!events[event]) return this;
    events[event] = events[event].filter(
      (listener) => listener.callback !== callback
    );
    return this;
  }

  function emit<T = unknown>(event: string, ...args: T[]): unknown[] {
    const listeners = events[event];
    if (!listeners) return [];

    const results: unknown[] = [];
    const newListeners: Listener[] = [];
    for (const listener of listeners) {
      const result = listener.callback(...args);
      results.push(result);
      if (!listener.once) {
        newListeners.push(listener);
      }
    }
    events[event] = newListeners;
    return results;
  }

  return { on, off, emit };
}
