export function createRateLimiter(): RateLimiter {
  const store = new Map<string, WindowState>();

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrCreateState(store, key, nowMs);
      if (state.count < 3) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const state = store.get(key);
      if (!state || nowMs - state.windowStart >= 1000) {
        return 3;
      }
      return Math.max(0, 3 - state.count);
    },
    reset(key: string): void {
      store.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

interface WindowState {
  windowStart: number;
  count: number;
}

function getOrCreateState(
  store: Map<string, WindowState>,
  key: string,
  nowMs: number
): WindowState {
  let state = store.get(key);
  if (state && nowMs - state.windowStart < 1000) {
    return state;
  }
  state = { windowStart: nowMs, count: 0 };
  store.set(key, state);
  return state;
}
