    set(key, value, nowMs, ttlMs) {
      const expiresAt = nowMs + (ttlMs ?? 1000);
      store.set(key, { value, expiresAt });
    },

    get(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },

    delete(key) {
      return store.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const [key, entry] of store.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          store.delete(key);
        }
      }
      return count;
    },

    clear() {
      store.clear();
    },
  };
}
