type Listener = (...args: any[]) => any;

interface EventEmitter {
  on(event: string | symbol, listener: Listener): void;
  once(event: string | symbol, listener: Listener): void;
  off(event: string | symbol, listener: Listener): void;
  emit(event: string | symbol, ...args: any[]): any[];
}

interface ListenerEntry {
  fn: Listener;
  once: boolean;
}

export function createEventEmitter(): EventEmitter {
  const events = new Map<string | symbol, ListenerEntry[]>();

  const on = (event: string | symbol, listener: Listener) => {
    const arr = events.get(event) ?? [];
    arr.push({ fn: listener, once: false });
    events.set(event, arr);
  };

  const once = (event: string | symbol, listener: Listener) => {
    const arr = events.get(event) ?? [];
    arr.push({ fn: listener, once: true });
    events.set(event, arr);
  };

  const off = (event: string | symbol, listener: Listener) => {
    const arr = events.get(event);
    if (!arr) return;
    const index = arr.findIndex(entry => entry.fn === listener);
    if (index !== -1) {
      arr.splice(index, 1);
      if (arr.length === 0) {
        events.delete(event);
      } else {
        events.set(event, arr);
      }
    }
  };

  const emit = (event: string | symbol, ...args: any[]): any[] => {
    const arr = events.get(event);
    if (!arr) return [];
    const results: any[] = [];
    const remaining: ListenerEntry[] = [];
    for (const entry of arr) {
      results.push(entry.fn(...args));
      if (!entry.once) {
        remaining.push(entry);
      }
    }
    if (remaining.length > 0) {
      events.set(event, remaining);
    } else {
      events.delete(event);
    }
    return results;
  };

  return { on, once, off, emit };
}
