export function createEventEmitter(): EventEmitter {
  const events = new Map<
    string,
    Array<{ fn: Listener; once: boolean }>
  >();

  return {
    on(event, listener) {
      const arr = events.get(event) ?? [];
      arr.push({ fn: listener, once: false });
      events.set(event, arr);
      return arr.length;
    },

    once(event, listener) {
      const arr = events.get(event) ?? [];
      arr.push({ fn: listener, once: true });
      events.set(event, arr);
      return arr.length;
    },

    off(event, listener) {
      const arr = events.get(event);
      if (!arr) return false;
      const index = arr.findIndex((l) => l.fn === listener);
      if (index === -1) return false;
      arr.splice(index, 1);
      if (arr.length === 0) events.delete(event);
      else events.set(event, arr);
      return true;
    },

    emit(event, payload) {
      const arr = events.get(event);
      if (!arr) return [];
      const results: unknown[] = [];
      for (let i = 0; i < arr.length; i++) {
        const { fn, once } = arr[i];
        results.push(fn(payload));
        if (once) {
          arr.splice(i, 1);
          i--;
        }
      }
      if (arr.length === 0) events.delete(event);
      else events.set(event, arr);
      return results;
    },

    listenerCount(event) {
      const arr = events.get(event);
      return arr ? arr.length : 0;
    },
  };
}
