export type Listener = (...args: any[]) => any;

export function createEventEmitter() {
  type ListenerEntry = { fn: Listener; once: boolean };
  const events = new Map<string, ListenerEntry[]>();

  function on(event: string, listener: Listener) {
    const list = events.get(event) ?? [];
    list.push({ fn: listener, once: false });
    events.set(event, list);
    return this;
  }

  function once(event: string, listener: Listener) {
    const list = events.get(event) ?? [];
    list.push({ fn: listener, once: true });
    events.set(event, list);
    return this;
  }

  function off(event: string, listener: Listener) {
    const list = events.get(event);
    if (!list) return this;
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === listener) {
        list.splice(i, 1);
        break;
      }
    }
    if (list.length === 0) events.delete(event);
    return this;
  }

  function emit(event: string, ...args: any[]): any[] {
    const list = events.get(event);
    if (!list) return [];
    const results: any[] = [];
    // Since we might modify list during iteration, make a copy of indices
    const listeners = [...list];
    for (const entry of listeners) {
      results.push(entry.fn(...args));
      if (entry.once) {
        off(event, entry.fn);
      }
    }
    return results;
  }

  return {
    on,
    once,
    off,
    emit,
  };
}

