export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  type InternalListener = { listener: Listener; once: boolean }

  const listenersMap = new Map<string, InternalListener[]>()

  const emitter: EventEmitter = {
    on(event, listener) {
      const evListeners = listenersMap.get(event) ?? []
      evListeners.push({ listener, once: false })
      listenersMap.set(event, evListeners)
      return evListeners.length
    },

    once(event, listener) {
      const evListeners = listenersMap.get(event) ?? []
      evListeners.push({ listener, once: true })
      listenersMap.set(event, evListeners)
      return evListeners.length
    },

    off(event, listener) {
      const evListeners = listenersMap.get(event)
      if (!evListeners) return false
      const idx = evListeners.findIndex(l => l.listener === listener)
      if (idx === -1) return false
      evListeners.splice(idx, 1)
      if (evListeners.length === 0) listenersMap.delete(event)
      else listenersMap.set(event, evListeners)
      return true
    },

    emit(event, payload) {
      const evListeners = listenersMap.get(event)
      if (!evListeners) return []
      const snapshot = evListeners.slice()
      const results = snapshot.map(l => l.listener(payload))
      const hasOnce = snapshot.some(l => l.once)
      if (hasOnce) {
        const remaining = evListeners.filter(l => !l.once)
        if (remaining.length === 0) listenersMap.delete(event)
        else listenersMap.set(event, remaining)
      }
      return results
    },

    listenerCount(event) {
      return listenersMap.get(event)?.length ?? 0
    }
  }

  return emitter
}

export function createRateLimiter() {
    const WINDOW_MS = 1000;
    const LIMIT = 3;
    const state = new Map<string, { windowStart: number; count: number }>();

    return {
        allow(key: string, nowMs: number): boolean {
            const windowStart = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
            const entry = state.get(key);
            if (!entry || entry.windowStart !== windowStart) {
                state.set(key, { windowStart, count: 1 });
                return true;
            }
            if (entry.count < LIMIT) {
                entry.count += 1;
                return true;
            }
            return false;
        },
        reset(key: string): void {
            state.delete(key);
        }
    };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const states = new Map<string, { windowStart: number; count: number }>()

  function getState(key: string, nowMs: number) {
    let state = states.get(key)
    if (!state) {
      state = { windowStart: nowMs, count: 0 }
      states.set(key, state)
    } else if (nowMs - state.windowStart >= windowMs) {
      state.windowStart = nowMs
      state.count = 0
    }
    return state
  }

  return {
    allow(key, nowMs) {
      const state = getState(key, nowMs)
      if (state.count < limit) {
        state.count += 1
        return true
      }
      return false
    },

    remaining(key, nowMs) {
      const state = states.get(key)
      if (!state) return limit
      if (nowMs - state.windowStart >= windowMs) return limit
      const remaining = limit - state.count
      return remaining > 0 ? remaining : 0
    },

    reset(key) {
      states.delete(key)
    }
  }
}

