export function createTtlCache() {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs?: number
  ): void {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    store.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const item = store.get(key);
    if (!item) return undefined;
    if (nowMs >= item.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return item.value;
  }

  function has(key: string, nowMs: number): boolean {
    const item = store.get(key);
    if (!item) return false;
    if (nowMs >= item.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  }

  function deleteKey(key: string): boolean {
    return store.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [_, item] of store.entries()) {
      if (nowMs >= item.expiresAt) {
        store.delete(item);
        continue;
      }
      count++;
    }
    return count;
  }

  function clear(): void {
    store.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000): void {
      const expiresAt = nowMs + ttlMs;
      store.set(key, { value, expiresAt });
    },

    get(key, nowMs): unknown {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },

    has(key, nowMs): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) return false;
      return true;
    },

    delete(key): boolean {
      return store.delete(key);
    },

    size(nowMs): number {
      let count = 0;
      for (const { expiresAt } of store.values()) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    },

    clear(): void {
      store.clear();
    },
  };
}

