type Listener<T> = ((...args: any[]) => T) | ((...args: any[]) => void);

type EventEmitter<T> = {
  on(eventName: string, listener: Listener<T>): void;
  once(eventName: string, listener: Listener<T>): void;
  off(eventName: string, listener: Listener<T>): void;
  emit(eventName: string, ...args: any[]): T[];
};

function createEventEmitter<T extends string>() {
  const listeners: { [key in T]: Listener<T>[] } = {};

  return {
    on(eventName: T, listener: Listener<T>) {
      if (!listeners[eventName]) listeners[eventName] = [];
      listeners[eventName].push(listener);
    },
    once(eventName: T, listener: Listener<T>) {
      this.on(eventName, (event, ...args) => {
        listener(...args);
        this.off(eventName, listener);
      });
    },
    off(eventName: T, listener: Listener<T>) {
      if (listeners[eventName]) {
        const index = listeners[eventName].indexOf(listener);
        if (index !== -1) listeners[eventName].splice(index, 1);
      }
    },
    emit(eventName: T, ...args: any[]): T[] {
      if (listeners[eventName]) {
        const result = listeners[eventName].map((listener) => listener(...args));
        listeners[eventName] = []; // clear the listeners array
        return result;
      }
      return [];
    },
  };
}

export { createEventEmitter };
