export function createEventEmitter(): {
  on(event: string, listener: (payload: unknown) => unknown): number
  once(event: string, listener: (payload: unknown) => unknown): number
  off(event: string, listener: (payload: unknown) => unknown): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
} {
  const listeners: { [event: string]: (payload: unknown)[] } = {};
  const eventCounts: { [event: string]: number } = {};

  function on(event: string, listener: (payload: unknown) => unknown): number {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push(listener);
    eventCounts[event] = listeners[event].length;
    return eventCounts[event];
  }

  function once(event: string, listener: (payload: unknown) => unknown): number {
    function wrapper(payload: unknown): unknown {
      const result = listener(payload);
      listeners[event].splice(listeners[event].indexOf(wrapper), 1);
      if (listeners[event].length === 0) delete listeners[event];
      return result;
    }
    const count = on(event, wrapper);
    eventCounts[event]--;
    return count;
  }

  function off(event: string, listener: (payload: unknown) => unknown): boolean {
    if (listeners[event]) {
      const index = listeners[event].indexOf(listener);
      if (index !== -1) {
        listeners[event].splice(index, 1);
        eventCounts[event]--;
        if (listeners[event].length === 0) delete listeners[event];
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload: unknown): unknown[] {
    if (listeners[event]) {
      const results: unknown[] = [];
      for (const listener of listeners[event]) {
        results.push(listener(payload));
      }
      return results;
    }
    return [];
  }

  function listenerCount(event: string): number {
    return eventCounts[event] || 0;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}
