export function createRateLimiter(): RateLimiter {
  const rateLimiters: { [key: string]: {
    limit: number;
    windowMs: number;
    windowStart: number;
    quota: number;
  }} = {};
  return {
    allow: (key: string, nowMs: number): boolean => {
      if (!rateLimiters[key]) {
        rateLimiters[key] = {
          limit: 3,
          windowMs: 1000,
          windowStart: nowMs,
          quota: 0,
        };
      }
      const { limit, windowMs, quota } = rateLimiters[key];
      if (quota >= limit) {
        return false;
      }
      const nowWindowStart = nowMs - windowMs;
      if (nowWindowStart >= rateLimiters[key].windowStart) {
        rateLimiters[key].windowStart = nowWindowStart;
        rateLimiters[key].quota = 0;
      }
      rateLimiters[key].quota++;
      return true;
    },
    remaining: (key: string, nowMs: number): number => {
      if (!rateLimiters[key]) {
        return -1;
      }
      const { limit, windowMs } = rateLimiters[key];
      const nowWindowStart = nowMs - windowMs;
      if (nowWindowStart >= rateLimiters[key].windowStart) {
        return -1;
      }
      return limit - rateLimiters[key].quota;
    },
    reset: (key: string): void => {
      if (!rateLimiters[key]) {
        return;
      }
      delete rateLimiters[key];
    },
  };
}
