  const now = (ms: number) => BigInt(ms);

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
    const expiresAt = ttlMs ? nowMs + BigInt(ttlMs) : nowMs + now(BigInt(1000));
    cache[key] = { value, expiresAt };
  };

  const get = (key: string, nowMs: number) => cache[key]?.value ?? undefined;

  const has = (key: string, nowMs: number) => cache[key] !== undefined;

  const delete_ = (key: string) => {
    if (cache[key]) {
      delete cache[key];
      return true;
    }
    return false;
  };

  const size = (nowMs: number) => {
    let count = 0;
    for (const key in cache) {
      if (cache[key].expiresAt <= nowMs) continue;
      count++;
    }
    return count;
  };

  const clear = () => {
    for (const key in cache) {
      delete cache[key];
    }
  };

  return {
    set,
    get,
    has,
    delete_,
