export const createTtlCache = (nowMs: number) => {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const ttlMs = 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const expiresAt = nowMs + (ttlMs || ttlMs);
      cache.delete(key);
      cache.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      const cacheItem = cache.get(key);
      if (!cacheItem) return undefined;
      if (nowMs >= cacheItem.expiresAt) return undefined;
      return cacheItem.value;
    },
    has(key: string, nowMs: number): boolean {
      const cacheItem = cache.get(key);
      if (!cacheItem) return false;
      if (nowMs >= cacheItem.expiresAt) return false;
      return true;
    },
    delete(key: string): boolean {
      const cacheItem = cache.get(key);
      if (!cacheItem) return false;
      cache.delete(key);
      return true;
    },
    size(nowMs: number): number {
      const liveCounts = 0;
      for (const [k, v] of cache) {
        if (nowMs >= v.expiresAt) continue;
        liveCounts++;
      }
      return liveCounts;
    },
    clear() {
      cache.clear();
    },
  };
};
