type Listener = (payload: unknown) => unknown;

interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
}

interface ListenerEntry {
    listener: Listener;
    once: boolean;
}

export function createEventEmitter(): EventEmitter {
    const listeners: Record<string, ListenerEntry[]> = {};

    return {
        on(event, listener) {
            const entries = listeners[event] || [];
            entries.push({ listener, once: false });
            listeners[event] = entries;
            return entries.length;
        },

        once(event, listener) {
            const entries = listeners[event] || [];
            entries.push({ listener, once: true });
            listeners[event] = entries;
            return entries.length;
        },

        off(event, listener) {
            const entries = listeners[event];
            if (!entries) return false;

            for (let i = 0; i < entries.length; i++) {
                if (entries[i].listener === listener) {
                    entries.splice(i, 1);
                    return true;
                }
            }
            return false;
        },

        emit(event, payload) {
            const entries = listeners[event] || [];
            const results: unknown[] = [];
            const onceEntries: ListenerEntry[] = [];

            for (const entry of entries) {
                results.push(entry.listener(payload));
                if (entry.once) onceEntries.push(entry);
            }

            for (const entry of onceEntries) {
                this.off(event, entry.listener);
            }

            return results;
        },

        listenerCount(event) {
            return (listeners[event] || []).length;
        },
    };
}
