            const elapsed = nowMs - entry.windowStart;

            if (elapsed >= 1000) {
                state[key] = { count: 1, windowStart: nowMs };
                return true;
            } else if (entry.count < 3) {
                state[key] = { count: entry.count + 1, windowStart: entry.windowStart };
                return true;
