```typescript
export function createEventEmitter(): EventEmitter {
    const listeners: Record<string, Listener[]> = {};
    const onceListeners: Record<string, { listener: Listener; once: true }[]> = {};

    return {
        on(event: string, listener: Listener): number {
            if (!listeners[event]) listeners[event] = [];
            listeners[event].push(listener);
            return listeners[event].length;
        },

        once(event: string, listener: Listener): number {
            if (!onceListeners[event]) onceListeners[event] = [];
            onceListeners[event].push({ listener, once: true });
            return listeners[event] ? listeners[event].length + onceListeners[event].length : onceListeners[event].length;
        },

        off(event: string, listener: Listener): boolean {
            const fromRegular = listeners[event] ? listeners[event].some((_, i) => {
                if (listeners[event][i] === listener) {
                    listeners[event].splice(i, 1);
                    return true;
                }
                return false;
            }) || false : false;

            if (fromRegular) return true;

            const fromOnce = onceListeners[event] ? onceListeners[event].some((_, i) => {
                if (onceListeners[event][i].listener === listener) {
                    onceListeners[event].splice(i, 1);
                    return true;
                }
                return false;
            }) || false : false;

            return fromOnce;
        },

        emit(event: string, payload: unknown): unknown[] {
            const results: unknown[] = [];
            const onceKeys = Object.keys(onceListeners);

            if (onceKeys.includes(event) && onceListeners[event].length > 0) {
                // Create a shallow copy to avoid modifying while iterating in nested loops
                const onceToEmit = [...onceListeners[event]];
                for (const { listener } of onceToEmit) {
                    results.push(listener(payload));
                    // Remove after first invocation
                    const index = onceListeners[event].findIndex(l => l.listener === listener);
                    if (index !== -1) onceListeners[event].splice(index, 1);
                }
            }

            if (listeners[event] && listeners[event].length > 0) {
                const listenersToEmit = [...listeners[event]];
                for (const listener of listenersToEmit) {
                    results.push(listener(payload));
                }
            }

            return results;
        },

        listenerCount(event: string): number {
            return (listeners[event] ? listeners[event].length : 0) + (onceListeners[event] ? onceListeners[event].length : 0);
        }
    };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
}
