interface RateLimiter {
    allow(key: string, nowMs: number): boolean
    remaining(key: string, nowMs: number): number
    reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
    const windowMs = 1000
    const limit = 3
    const keyStates = new Map<string, { count: number, windowStart: number }>()

    return {
        allow(key, nowMs) {
            const state = this._getState(key, nowMs)
            if (!state.isNewWindow) {
                state.newlyIncluded = true
            }
            return this._decideAllow(state, nowMs)
        },
        remaining(key, nowMs) {
            const state = this._getState(key, nowMs)
            return state.isNewWindow ? limit : Math.max(0, limit - state.count)
        },
        reset(key) {
            keyStates.delete(key)
        },
        _getState(key, nowMs) {
            const existing = keyStates.get(key) || {}
            return {
                ...existing,
                windowStart: existing.windowStart || nowMs,
                isNewWindow: nowMs - existing.windowStart >= windowMs,
                newlyIncluded: !!existing,
                count: (existing.count || 0) + (existing.isNewWindow ? 0 : 0)
            }
        },
        _decideAllow(state, nowMs) {
            if (!state.newlyIncluded) {
                if (state.isNewWindow) {
                    keyStates.set(state.key, { count: 0, windowStart: nowMs })
                }
                return false
            } else {
                if (state.isNewWindow) {
                    keyStates.set(state.key, { count: 1, windowStart: nowMs })
                } else {
                    state.count += 1
                }
                return state.count <= limit
            }
        }
    }
}

// Internal fix: The above implementation had a critical issue where state.key was undefined.
// Here's a corrected version:
export function createRateLimiter(): RateLimiter {
    const windowMs = 1000
    const limit = 3

    return {
        allow(key: string, nowMs: number): boolean {
            const state = getOrInitializeState(key)
            if (nowMs - state.windowStart >= windowMs) {
                state.count = 0
                state.windowStart = nowMs
            }
            if (state.count < limit) {
                state.count++
                return true
            }
            return false
        },
        remaining(key: string, nowMs: number): number {
            const state = getOrInitializeState(key)
            if (nowMs - state.windowStart >= windowMs) {
                state.count = 0
                state.windowStart = nowMs
            }
            return Math.max(0, limit - state.count)
        },
        reset(key: string): void {
            keyStates.delete(key)
        }
    }

    function getOrInitializeState(key: string) {
        let state = keyStates.get(key)
        if (!state) {
            state = { count: 0, windowStart: 0 }
            keyStates.set(key, state)
        }
        return state
    }

    const keyStates = new Map<string, { count: number, windowStart: number }>()
}
