    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
};

export function createTtlCache(): TtlCache {
    const store: Record<string, { value: unknown; expiresAt: number }> = {};
    const DEFAULT_TTL_MS = 1000;

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs = DEFAULT_TTL_MS): void {
            if (ttlMs >= 0) {
                store[key] = { value, expiresAt: nowMs + ttlMs };
            } else {
                delete store[key];
            }
        },
        get(key: string, nowMs: number): unknown {
            const entry = store[key];
            if (entry && nowMs < entry.expiresAt) {
                return entry.value;
            }
            return undefined;
        },
        has(key: string, nowMs: number): boolean {
            const entry = store[key];
            return entry ? nowMs < entry.expiresAt : false;
        },
        delete(key: string): boolean {
            const exists = key in store;
            delete store[key];
            return exists;
        },
        size(nowMs: number): number {
            return Object.keys(store).reduce((count, key) => {
                const entry = store[key];
                return entry && nowMs < entry.expiresAt ? count + 1 : count;
            }, 0);
        },
        clear(): void {
            Object.keys(store).forEach(key => delete store[key]);
        }
    };
}
