export function createEventEmitter() {
  const listeners: Record<string, Listener[]> = {};
  const onceListeners: Record<string, Listener[]> = {};

  return {
    on(event, listener) {
      const events = listeners[event] ??= [];
      events.push(listener);
      return events.length;
    },
    once(event, listener) {
      const events = onceListeners[event] ??= [];
      events.push(listener);
      return events.length;
    },
    off(event, listener) {
      if (listeners[event]) {
        return (listeners[event] = listeners[event]?.filter(l => l !== listener)).length > 0;
      }
      if (onceListeners[event]) {
        return (onceListeners[event] = onceListeners[event]?.filter(l => l !== listener)).length > 0;
      }
      return false;
    },
    emit(event, payload) {
      const results: unknown[] = [];
      if (listeners[event]) {
        results.push(...listeners[event].map(listener => listener(payload)));
      }
      if (onceListeners[event]) {
        onceListeners[event] = [];
        results.push(...onceListeners[event].map(listener => listener(payload)));
      }
      return results;
    },
    listenerCount(event) {
      return (listeners[event]?.length ?? 0) + (onceListeners[event]?.length ?? 0);
    },
  };
}
