function createRateLimiter(): RateLimiter {
    const state: Record<string, { count: number; startMs: number }> = {};

    return {
        allow(key, nowMs) {
            const current = state[key];
            const elapsed = nowMs - (current?.startMs ?? nowMs);
            if (elapsed >= 1000) {
                state[key] = { count: 0, startMs: nowMs };
                return true;
            }
            if (!current || (current.count < 3 && elapsed < 1000)) {
                if (!current || current.count < 3) {
                    current && 'count' in current ? current.count++ : state[key] = { count: 1, startMs: current.startMs };
                    return true;
                }
            }
            return false;
        },
        reset(key) {
            delete state[key];
        }
    };
}
