type TtlCache = {
  private cache: Map<string, { value: unknown; expiresAt: number }>;
  private defaultTtlMs: number;
  private nowMs: () => number;

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
};

function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const defaultTtlMs = 1000;
  const nowMs = () => Date.now();

  const cacheInstance: TtlCache = {
    cache,
    defaultTtlMs,
    nowMs,

    set(key: string, value: unknown, nowMs: number, ttlMs = defaultTtlMs) {
      const expiresAt = nowMs + (ttlMs === 0 ? 0 : ttlMs);
      this.cache.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = this.cache.get(key);
      if (!entry || nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = this.cache.get(key);
      return entry && nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return this.cache.delete(key);
    },

    size(nowMs: number): number {
      return Array.from(this.cache.values())
        .filter((entry) => nowMs < entry.expiresAt)
        .length;
    },

    clear() {
      this.cache.clear();
    },
  };

  return cacheInstance;
}
