export function createRateLimiter() {
  const quotaMap = new Map<string, number[]>();
  const windowSizeMs = 1000;

  const rateLimitCheck = (key: string, nowMs: number) => {
    const keyQuota = quotaMap.get(key) ?? [0];
    const windowStart = nowMs - ((nowMs / windowSizeMs) | 0) * windowSizeMs;

    const existingQuota = keyQuota.filter(quota => quota < windowStart).length;
    const windowQuota = keyQuota.filter(quota => windowStart <= quota && quota < nowMs).length;

    if (existingQuota + windowQuota < 3) {
      return false;
    }

    quotaMap.set(key, [...keyQuota, nowMs]);
    return true;
  };

  return {
    limit: (key: string, nowMs: number) => rateLimitCheck(key, nowMs),
    reset: (key: string) => {
      quotaMap.set(key, []);
    },
  };
}
