type RateLimiterState = {
  count: number;
  windowStart: number;
};

export function createRateLimiter(): RateLimiter {
  const stores: Record<string, RateLimiterState> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const state = stores[key];
      if (!state) {
        stores[key] = { count: 1, windowStart: nowMs };
        return true;
      }

      const windowEnd = state.windowStart + 1000;
      if (nowMs >= windowEnd) {
        stores[key] = { count: 1, windowStart: nowMs };
        return true;
      }

      if (state.count < 3) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const state = stores[key];
      if (!state) return 0;

      const windowEnd = state.windowStart + 1000;
      if (nowMs >= windowEnd) {
        return 3 - 1;
      }
      return Math.max(0, 3 - state.count);
    },
    reset(key: string): void {
      delete stores[key];
    }
  };
}
