import { EventEmitter } from 'events';

export function createEventEmitter() {
  const listenersByName = new Map<string, Array<(arg: any) => void>>();
  const oneTimeListenersByName = new Map<string, Array<(arg: any) => boolean>>();

  return {
    on(eventName: string, listener: (arg: any) => any): void {
      if (listenersByName.has(eventName)) {
        listenersByName.get(eventName)!.push(listener);
      } else {
        listenersByName.set(eventName, [listener]);
      }
    },
    once(eventName: string, listener: (arg: any) => boolean): void {
      oneTimeListenersByName.set(eventName, [listener]);
    },
    off(eventName: string, listener: (arg: any) => any): void {
      if (listenersByName.has(eventName)) {
        const nameListeners = listenersByName.get(eventName)!;
        const index = nameListeners.findIndex((l: any) => l === listener);
        if (index !== -1) {
          nameListeners.splice(index, 1);
        }
      }
    },
    emit(eventName: string, arg: any): any {
      const eventListeners = listenersByName.get(eventName) || [];
      const oneTimeListeners = oneTimeListenersByName.get(eventName) || [];

      const result: any[] = [];
      // Emit regular listeners
      for (const listener of eventListeners) {
        listener(arg);
        result.push(listener(arg));
      }
      // Emit one-time listeners
      for (const listener of oneTimeListeners) {
        if (listener(arg)) {
          eventListeners.push(listener);
          result.push(listener(arg));
        }
        oneTimeListenersByName.delete(eventName);
      }
      return result;
    },
  };
}
