function createRateLimiter() {
  const limiter: Record<string, { windowStartMs: number }> = {};

  const rateLimiter = {
    async useRateLimiter(nowMs: number, key: string): Promise<boolean> {
      if (!limiter[key]) {
        limiter[key] = { windowStartMs: nowMs };
        return true;
      }

      const windowDurationMs = 1000;
      const expiryWindow = (nowMs - limiter[key].windowStartMs) / windowDurationMs;
      const requestCount = Math.max(0, expiryWindow - Math.floor(expiryWindow));

      if (requestCount < 3) {
        limiter[key].windowStartMs = nowMs;
        return true;
      }
      return false;
    },

    reset(key: string) {
      delete limiter[key];
    },
  };

  return rateLimiter;
}
