type RateLimiterState = { count: number; lastReset: number };

export function createRateLimiter(): RateLimiter {
  const state: Record<string, RateLimiterState> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const stateEntry = state[key];
      if (!stateEntry || nowMs - stateEntry.lastReset >= 1000) {
        state[key] = { count: 0, lastReset: nowMs };
      } else {
        if (stateEntry.count < 3) {
          state[key].count += 1;
          return true;
        }
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const stateEntry = state[key];
      if (!stateEntry || nowMs - stateEntry.lastReset >= 1000) {
        return 3;
      } else {
        return Math.max(0, 3 - stateEntry.count);
      }
    },
    reset(key: string): void {
      delete state[key];
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
