export function createTodoApp() {
  const manager = new TodoManager();

  const addTodo = (text: string): Todo => {
    const todo = { id: manager.nextId, text, completed: false };
    manager.nextId += 1;
    manager.addTodoInternal(todo.id, todo.text, todo.completed);
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => {
    const existingTodo = manager.todos.find(todo => todo.id === id);
    return existingTodo || undefined;
  };

  const toggleTodo = (id: number): void => {
    const todo = manager.todos.find(todo => todo.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const todoExistsBeforeDeletion = manager.todos.some(todo => todo.id === id);
    manager.removeTodoById(id);
    return todoExistsBeforeDeletion;
  };

  const listTodos = (): Todo[] => [...manager.todos];
  const listCompleted = (): Todo[] => [...manager.todos.filter(todo => todo.completed)];
  const listPending = (): Todo[] => [...manager.todos.filter(todo => !todo.completed)];
  const clearCompleted = (): void => {
    manager.todos = manager.todos.filter(todo => !todo.completed);
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
