export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs = 1000) => {
      cache.set(key, { value, expiresAt: nowMs + ttlMs });
    },
    get: (key: string, nowMs: number) => {
      if (!cache.has(key)) return undefined;
      const { expiresAt } = cache.get(key)!;
      return nowMs >= expiresAt ? undefined : cache.get(key)!.value;
    },
    has: (key: string, nowMs: number) => {
      if (!cache.has(key)) return false;
      const { expiresAt } = cache.get(key)!;
      return nowMs < expiresAt;
    },
    delete: (key: string) => {
      return cache.delete(key);
    },
    size: (nowMs: number) => {
      const entries = cache.entries();
      let count = 0;
      for (const [_, { expiresAt }] of entries) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    },
    clear: () => cache.clear(),
  };
}

