export function createRateLimiter() {
  const limit = 3;
  const windowMs = 1000;

  const store = new Map<string, { windowStart: number; count: number }>();

  function resetWindow(key: string, nowMs: number) {
    const entry = store.get(key);
    if (!entry) {
      store.set(key, { windowStart: nowMs, count: 0 });
    } else {
      if (nowMs - entry.windowStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.count = 0;
      }
    }
  }

  function allow(key: string, nowMs: number): boolean {
    // ensure entry exists
    let entry = store.get(key);
    if (!entry) {
      entry = { windowStart: nowMs, count: 0 };
      store.set(key, entry);
    }
    // boundary reset
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    if (entry.count < limit) {
      entry.count++;
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    let entry = store.get(key);
    if (!entry) {
      // no state => full quota
      return limit;
    }
    if (nowMs - entry.windowStart >= windowMs) {
      // reset for remaining too
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    return Math.max(0, limit - entry.count);
  }

  function reset(key: string): void {
    store.delete(key);
  }

  const api = {
    allow,
    remaining,
    reset,
  };
  return api;
}
```

