export function createEventEmitter(): EventEmitter {
  type Listener = (payload: unknown) => unknown;
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  const getArray = (event: string) => {
    if (!listeners.has(event)) listeners.set(event, []);
    return listeners.get(event)!;
  };

  return {
    on(event, listener) {
      const arr = getArray(event);
      arr.push({ fn: listener, once: false });
      return arr.length;
    },
    once(event, listener) {
      const arr = getArray(event);
      arr.push({ fn: listener, once: true });
      return arr.length;
    },
    off(event, listener) {
      const arr = listeners.get(event);
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].fn === listener) {
          arr.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event, payload) {
      const arr = listeners.get(event);
      if (!arr) return [];
      const results: unknown[] = [];
      let i = 0;
      while (i < arr.length) {
        const { fn, once } = arr[i];
        const ret = fn(payload);
        results.push(ret);
        if (once) {
          arr.splice(i, 1);
        } else {
          i++;
        }
      }
      return results;
    },
    listenerCount(event) {
      return listeners.get(event)?.length ?? 0;
    },
  } as EventEmitter;
}

export function createRateLimiter() {
  const states = new Map<string, { timestamps: number[] }>();
  return {
    allow(key: string, nowMs: number): boolean {
      const state = states.get(key) ?? { timestamps: [] };
      const recent = state.timestamps.filter(t => t > nowMs - 1000);
      if (recent.length >= 3) {
        return false;
      }
      recent.push(nowMs);
      state.timestamps = recent;
      states.set(key, state);
      return true;
    },
    reset(key: string): void {
      const state = states.get(key);
      if (state) {
        state.timestamps = [];
      }
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const store = new Map<string, { windowStart: number; count: number }>()

  const refreshWindow = (key: string, nowMs: number) => {
    const state = store.get(key)
    if (!state) {
      store.set(key, { windowStart: nowMs - (nowMs % windowMs), count: 0 })
      return
    }
    if (nowMs - state.windowStart >= windowMs) {
      state.windowStart = nowMs - (nowMs % windowMs)
      state.count = 0
    }
  }

  return {
    allow(key, nowMs) {
      refreshWindow(key, nowMs)
      const state = store.get(key)!
      if (state.count < limit) {
        state.count++
        return true
      }
      return false
    },
    remaining(key, nowMs) {
      refreshWindow(key, nowMs)
      const state = store.get(key)
      if (!state) return limit
      const remaining = limit - state.count
      return remaining > 0 ? remaining : 0
    },
    reset(key) {
      store.delete(key)
    },
  }
}

