  const defaultTTL = 1000;
  return {
    set(key, value, nowMs, ttlMs) {
      const expiresAt = nowMs + (ttlMs ?? defaultTTL);
      map.set(key, {value, expiresAt});
    },
    get(key, nowMs) {
      const entry = map.get(key);
      return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = map.get(key);
      return entry && nowMs < entry.expiresAt;
    },
    delete(key) {
      return map.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const {expiresAt} of map.values()) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    },
    clear() {
      map.clear();
    },
  };
}

