export function createRateLimiter() {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const stateMap = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = stateMap.get(key);
      if (!entry) {
        entry = { count: 0, windowStart: nowMs };
        stateMap.set(key, entry);
      }

      const elapsed = nowMs - entry.windowStart;
      if (elapsed >= WINDOW_MS) {
        entry.count = 0;
        entry.windowStart = nowMs;
      }

      if (entry.count < LIMIT) {
        entry.count += 1;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let entry = stateMap.get(key);
      if (!entry) {
        return LIMIT;
      }

      const elapsed = nowMs - entry.windowStart;
      if (elapsed >= WINDOW_MS) {
        entry.count = 0;
        entry.windowStart = nowMs;
      }

      return LIMIT - entry.count;
    },
    reset(key: string): void {
      stateMap.delete(key);
    }
  };
}
