type Listener = (...args: any[]) => any;
type EventHandler = {
  listeners: Listener[];
  onceListeners: Listener[];
};

function createEventEmitter(): { on: (eventName: string, listener: Listener) => void; off: (eventName: string, listener: Listener) => void; once: (eventName: string, listener: Listener) => void; emit: (eventName: string, ...args: any[]) => any[] } {
  const eventStore: { [eventName: string]: EventHandler } = {};

  const emitter = {
    on: (eventName: string, listener: Listener) => {
      if (!eventStore[eventName]) {
        eventStore[eventName] = { listeners: [], onceListeners: [] };
      }
      eventStore[eventName].listeners.push(listener);
    },
    off: (eventName: string, listener: Listener) => {
      if (eventStore[eventName]) {
        eventStore[eventName].listeners = eventStore[eventName].listeners.filter(l => l !== listener);
        eventStore[eventName].onceListeners = eventStore[eventName].onceListeners.filter(l => l !== listener);
      }
    },
    once: (eventName: string, listener: Listener) => {
      if (!eventStore[eventName]) {
        eventStore[eventName] = { listeners: [], onceListeners: [] };
      }
      eventStore[eventName].onceListeners.push(listener);
    },
    emit: (eventName: string, ...args: any[]): any[] => {
      const results: any[] = [];
      const listeners = [...eventStore[eventName]?.listeners || [], ...eventStore[eventName]?.onceListeners || []];
      for (const listener of listeners) {
        const result = listener(...args);
        if (eventStore[eventName]?.onceListeners.includes(listener)) {
          eventStore[eventName].onceListeners = eventStore[eventName].onceListeners.filter(l => l !== listener);
        }
        results.push(result);
      }
      return results;
    }
  };

  return emitter;
}

export { createEventEmitter };
