export function createEventEmitter(): EventEmitter {
  const listeners: { [event: string]: Listener[] } = {};

  const on = (event: string, listener: Listener): number => {
    if (!listeners[event]) {
      listeners[event] = [];
    }
    listeners[event].push(listener);
    return listeners[event].length;
  };

  const once = (event: string, listener: Listener): number => {
    const onceWrapper = (payload: unknown) => {
      listener(payload);
      off(event, onceWrapper);
    };
    return on(event, onceWrapper);
  };

  const off = (event: string, listener: Listener): boolean => {
    if (!listeners[event]) {
      return false;
    }
    const index = listeners[event].indexOf(listener);
    if (index === -1) {
      return false;
    }
    listeners[event].splice(index, 1);
    return true;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    if (!listeners[event]) {
      return [];
    }
    const results: unknown[] = [];
    for (const listener of listeners[event]) {
      results.push(listener(payload));
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    return listeners[event] ? listeners[event].length : 0;
  };

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}
