      listeners[event].push(callback);
    },
    once: (event: string, callback: (...args: any[]) => any) => {
      const handler = (...args: any[]) => {
        off(event, handler);
        callback(...args);
      };
      on(event, handler);
    },
    off: (event: string, callback: (...args: any[]) => any) => {
      if (listeners[event]) {
        listeners[event] = listeners[event].filter(cb => cb !== callback);
      }
    },
    emit: (event: string, ...args: any[]): any[] => {
      if (listeners[event]) {
        return listeners[event].map(callback => callback(...args));
      }
      return [];
    },
  };
}
