export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache: { [key: string]: { value: unknown, expiresAt: number } } = {}

  function set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
    cache[key] = { value, expiresAt: nowMs + ttlMs }
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache[key]
    if (entry && entry.expiresAt > nowMs) {
      return entry.value
    }
    return undefined
  }

  function has(key: string, nowMs: number): boolean {
    return get(key, nowMs) !== undefined
  }

  function delete(key: string): boolean {
    if (key in cache) {
      delete cache[key]
      return true
    }
    return false
  }

  function size(nowMs: number): number {
    return Object.keys(cache).filter(key => cache[key].expiresAt > nowMs).length
  }

  function clear(): void {
    cache = {}
  }

  return {
    set,
    get,
    has,
    delete,
    size,
    clear,
  }
}
