import {createRateLimiter} from './module';

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const cache: {[key: string]: number[]} = {};

  function allow(key: string, nowMs: number): boolean {
    if (!cache[key]) cache[key] = [];
    const window = cache[key];
    while (window.length && nowMs - window[0] >= windowMs) window.shift();
    if (window.length < limit) {
      window.push(nowMs);
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    if (!cache[key]) return limit;
    const window = cache[key];
    while (window.length && nowMs - window[0] >= windowMs) window.shift();
    return limit - window.length;
  }

  function reset(key: string): void {
    delete cache[key];
  }

  return {
    allow,
    remaining,
    reset
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
