import { EventEmitter } from 'events';

export function createEventEmitter() {
  const eventEmitter = new EventEmitter();
  return { on, off, emit };

  function on(eventName: string, listener: (...args: any[]) => any) {
    const wrappedListener = (...args: any[]) => {
      const result = listener(...args);
      return result;
    };
    if (!eventEmitter.listeners(eventName).includes(listener)) {
      eventEmitter.on(eventName, wrappedListener);
    }
    return () => off(eventName, listener);
  }

  function once(eventName: string, listenerOnce: (...args: any[]) => any) {
    return on(eventName, (...args: any[]) => {
      const result = listenerOnce(...args);
      off(eventName, listenerOnce);
      return result;
    });
  }

  function off(eventName: string, listener: (...args: any[]) => any) {
    const listeners = eventEmitter.listeners(eventName);
    const index = listeners.indexOf(listener);
    if (index > -1) {
      eventEmitter.removeListener(eventName, listeners[index]);
    }
  }

  function emit(eventName: string, ...args: any[]) {
    const listeners = eventEmitter.listeners(eventName);
    const results: any[] = [];
    for (const listener of listeners) {
      results.push(listener(...args));
    }
    return results;
  }
}
