import { Map } from "immutable";

interface RateLimiterConfig {
  limit: number;
  window: number;
}

export function createRateLimiter(nowMs: () => number, config: RateLimiterConfig = { limit: 3, window: 1000 }): { limit: (key: string) => boolean | undefined; reset: (key: string) => void } {
  const rateLimiter = {
    store: new Map<string, { hits: number, nextCheckAt: number }>(),
    limit(key: string): boolean | undefined {
      const { hits, nextCheckAt } = rateLimiter.store.get(key, { hits: 0, nextCheckAt: 0 });
      const now = nowMs();
      if (nextCheckAt > now) {
        return false;
      }
      const shouldAllow = hits < config.limit;
      if (shouldAllow) {
        rateLimiter.store = rateLimiter.store.set(key, { hits: hits + 1, nextCheckAt: Math.max(now + config.window, nextCheckAt + config.window) });
      } else {
        rateLimiter.store = rateLimiter.store.set(key, { hits, nextCheckAt: now + config.window });
      }
      return shouldAllow;
    },
    reset(key: string) {
      rateLimiter.store = rateLimiter.store.set(key, { hits: 0, nextCheckAt: 0 });
    }
  };
  return { limit: rateLimiter.limit.bind(rateLimiter), reset: rateLimiter.reset.bind(rateLimiter) };
}
