import { throttle } from 'lodash';

export function createRateLimiter(): RateLimiter {
  const limits = new Map<string, number>();
  const resets = new Map<string, number>();

  return {
    allow(key: string, nowMs: number): boolean {
      const limit = throttle(3);
      const reset = resets.get(key);
      if (nowMs - reset >= 1000) {
        resets.set(key, nowMs);
        limits.set(key, 3);
      }
      if (limits.has(key) && limits.get(key) > 0) {
        limits.set(key, limits.get(key) - 1);
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const reset = resets.get(key);
      if (nowMs - reset >= 1000) {
        resets.set(key, nowMs);
        limits.set(key, 3);
      }
      return limits.get(key) || 0;
    },
    reset(key: string): void {
      limits.delete(key);
      resets.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
