export function createEventEmitter() {
  const listeners: Map<string, Array<{ fn: (...args: any[]) => any; once: boolean }>> = new Map();

  return {
    on(event: string, fn: (...args: any[]) => any): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      eventListeners.push({ fn, once: false });
    },

    once(event: string, fn: (...args: any[]) => any): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      eventListeners.push({ fn, once: true });
    },

    off(event: string, fn: (...args: any[]) => any): void {
      const eventListeners = listeners.get(event);
      if (!eventListeners) {
        return;
      }
      const index = eventListeners.findIndex(l => l.fn === fn);
      if (index !== -1) {
        eventListeners.splice(index, 1);
      }
    },

    emit(event: string, ...args: any[]): any[] {
      const eventListeners = listeners.get(event);
      if (!eventListeners) {
        return [];
      }

      const results: any[] = [];
      const toCall = [...eventListeners];

      for (let i = 0; i < toCall.length; i++) {
        const listener = toCall[i];
        const result = listener.fn(...args);
        results.push(result);

        if (listener.once) {
          const index = eventListeners.indexOf(listener);
          if (index !== -1) {
            eventListeners.splice(index, 1);
          }
        }
      }

      return results;
    }
  };
}
