export interface EventEmitter {
  on(event: string, listener: Function): void;
  once(event: string, listener: Function): void;
  off(event: string, listener: Function): void;
  emit(event: string, ...args: any[]): any[];
}

export function createEventEmitter(): EventEmitter {
  const events: Map<string, { fn: Function; once: boolean }[]> = new Map();

  return {
    on(event: string, listener: Function): void {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ fn: listener, once: false });
    },

    once(event: string, listener: Function): void {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ fn: listener, once: true });
    },

    off(event: string, listener: Function): void {
      if (!events.has(event)) return;
      const listeners = events.get(event)!;
      const index = listeners.findIndex(item => item.fn === listener);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    },

    emit(event: string, ...args: any[]): any[] {
      if (!events.has(event)) return [];

      const listeners = events.get(event)!;
      const results: any[] = [];

      for (let i = listeners.length - 1; i >= 0; i--) {
        const { fn, once } = listeners[i];
        const result = fn(...args);
        results.unshift(result);

        if (once) {
          listeners.splice(i, 1);
        }
      }

      return results;
    }
  };
}
