export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, { fn: Listener; once: boolean }[]> = new Map()

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ fn: listener, once: false })
      return listeners.get(event)!.length
    },

    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ fn: listener, once: true })
      return listeners.get(event)!.length
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners.has(event)) {
        return false
      }
      const eventListeners = listeners.get(event)!
      const index = eventListeners.findIndex(reg => reg.fn === listener)
      if (index === -1) {
        return false
      }
      eventListeners.splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners.has(event)) {
        return []
      }
      const eventListeners = listeners.get(event)!
      const results: unknown[] = []
      const toRemove: number[] = []

      for (let i = 0; i < eventListeners.length; i++) {
        const { fn, once } = eventListeners[i]
        if (once) {
          toRemove.push(i)
        }
        results.push(fn(payload))
      }

      // Remove once listeners
      for (let i = toRemove.length - 1; i >= 0; i--) {
        eventListeners.splice(toRemove[i], 1)
      }

      return results
    },

    listenerCount(event: string): number {
      return listeners.has(event) ? listeners.get(event)!.length : 0
    }
  }
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
