export function createRateLimiter() {
  const state = new Map<string, { lastWindow: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const keyState = state.get(key);
      let lastWindow = 0;
      let count = 0;

      if (keyState) {
        lastWindow = keyState.lastWindow;
        count = keyState.count;
      }

      const windowStart = lastWindow;
      const windowEnd = windowStart + 1000;

      if (nowMs < windowEnd) {
        if (count >= 3) {
          return false;
        }
        state.set(key, { lastWindow: windowStart, count: count + 1 });
        return true;
      } else {
        state.set(key, { lastWindow: nowMs, count: 1 });
        return true;
      }
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
}
