export function createRateLimiter() {
  const limits = new Map<string, { count: number; windowStart: number }>();

  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const state = limits.get(key);

      if (!state || nowMs - state.windowStart >= windowMs) {
        limits.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      if (state.count < limit) {
        state.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = limits.get(key);

      if (!state || nowMs - state.windowStart >= windowMs) {
        return limit;
      }

      return Math.max(0, limit - state.count);
    },

    reset(key: string): void {
      limits.delete(key);
    }
  };
}
