export function createEventEmitter(): {
  addListener: (eventName: string, listener: (event: any, ...args: any[]) => any, isOneTime?: boolean) => void;
  removeListener: (eventName: string, listener: (event: any, ...args: any[]) => any) => void;
  emit: (eventName: string, ...args: any[]) => any[];
} {
  const eventMap = new Map<string, { callback: (event: any, ...args: any[]) => any; isOneTime: boolean }[]>();
  return {
    addListener: (eventName, listener, isOneTime = false) => {
      const listeners = eventMap.get(eventName) || [];
      const newListener = { callback: listener, isOneTime };
      listeners.push(newListener);
      eventMap.set(eventName, listeners);
    },
    removeListener: (eventName, listener) => {
      const listeners = eventMap.get(eventName);
      if (!listeners) return;
      const index = listeners.indexOf(listener);
      if (index !== -1) {
        listeners.splice(index, 1);
        eventMap.set(eventName, listeners);
      }
    },
    emit: (eventName, ...args: any[]) => {
      const listeners = eventMap.get(eventName) || [];
      const returns: any[] = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        const result = listener.callback(eventName, ...args);
        returns.push(result);
        if (listener.isOneTime) {
          listeners.splice(i, 1);
          i--; // adjust index due to splice
        }
      }
      return returns;
    }
  };
}
