export function createEventEmitter() {
  const eventListeners = new Map<string, Listener[]>();

  return {
    on(event: string, listener: Listener): number {
      if (!eventListeners.has(event)) {
        eventListeners.set(event, []);
      }
      const listeners = eventListeners.get(event)!;
      listeners.push(listener);
      return listeners.length;
    },

    once(event: string, listener: Listener): number {
      if (!eventListeners.has(event)) {
        eventListeners.set(event, []);
      }
      const listeners = eventListeners.get(event)!;
      const index = listeners.length;
      listeners.push((payload: unknown) => {
        if (index === listeners.length - 1) {
          listeners.splice(index, 1);
        }
      });
      return listeners.length;
    },

    off(event: string, listener: Listener): boolean {
      if (!eventListeners.has(event)) {
        return false;
      }
      const listeners = eventListeners.get(event)!;
      const index = listeners.indexOf(listener);
      if (index === -1) {
        return false;
      }
      listeners.splice(index, 1);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!eventListeners.has(event)) {
        return [];
      }
      const listeners = eventListeners.get(event)!;
      const results: unknown[] = [];
      for (let i = 0; i < listeners.length; i++) {
        results.push(listeners[i](payload));
      }
      return results;
    },

    listenerCount(event: string): number {
      if (!eventListeners.has(event)) {
        return 0;
      }
      return eventListeners.get(event)!.length;
    }
