    delete(key) {
      const entry = cache.get(key);
      if (entry) {
        cache.delete(key);
        return true;
      }
      return false;
    },
    size(nowMs) {
      let count = 0;
      for (const [key, { expiresAt }] of cache.entries()) {
        if (nowMs < expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
