export function createRateLimiter(): RateLimiter {
  const cache: Record<string, RateLimiterState> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const state = cache[key] || {
        count: 0,
        lastAllowed: 0,
        windowEnd: 0
      };

      if (state.count >= state.windowEnd - nowMs) {
        state.count = 0;
        state.lastAllowed = nowMs;
        state.windowEnd = nowMs;
      }

      if (state.count < 3) {
        state.count++;
        state.lastAllowed = nowMs;
        state.windowEnd = nowMs;
      }

      return state.count < 3;
    },

    remaining(key: string, nowMs: number): number {
      const state = cache[key] || {
        count: 0,
        lastAllowed: 0,
        windowEnd: 0
      };

      if (state.count < 3) return state.count;

      const windowEnd = state.windowEnd || nowMs;
      const windowDuration = windowEnd - nowMs;
      const remaining = 3 - (state.count - windowDuration);

      if (nowMs - state.lastAllowed >= 1000) {
        state.count = 0;
        state.lastAllowed = nowMs;
        state.windowEnd = nowMs;
      }

      return remaining;
    },

    reset(key: string) {
      if (cache[key]) {
        cache[key] = {
          count: 0,
          lastAllowed: 0,
          windowEnd: 0
        };
      }
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
