function createEventEmitter() {
  const listenersMap = new Map<string, Listener[]>();

  return {
    on(event: string, listener: (...args: any[]) => any): void {
      const listeners = listenersMap.get(event) || [];
      listeners.push({ callback: listener, once: false });
      listenersMap.set(event, listeners);
    },
    once(event: string, listener: (...args: any[]) => any): void {
      const listeners = listenersMap.get(event) || [];
      listeners.push({ callback: listener, once: true });
      listenersMap.set(event, listeners);
    },
    off(event: string, listener: (...args: any[]) => any): void {
      const listeners = listenersMap.get(event);
      if (!listeners) return;
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].callback === listener) {
          listeners.splice(i, 1);
          return;
        }
      }
    },
    emit(event: string, ...args: any[]): any[] {
      const listeners = listenersMap.get(event) || [];
      const copy = [...listeners];
      const results: any[] = [];
      for (const listener of copy) {
        const result = listener.callback(...args);
        results.push(result);
        if (listener.once) {
          const index = listeners.indexOf(listener);
          if (index !== -1) {
            listeners.splice(index, 1);
          }
        }
      }
      return results;
    }
  };
}

