export function createRateLimiter(): RateLimiter {
  const map = new Map<string, { windowStart: number, remaining: number }>();
  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      let state = map.get(key);
      if (!state) {
        const windowStart = nowMs - (nowMs % windowMs);
        state = { windowStart, remaining: limit };
        map.set(key, state);
        return true;
      }

      const { windowStart, remaining } = state;

      if (nowMs - windowStart >= windowMs) {
        const newWindowStart = nowMs - (nowMs % windowMs);
        map.set(key, { windowStart: newWindowStart, remaining: limit });
        return true;
      }

      if (remaining > 0) {
        map.set(key, { windowStart, remaining: remaining - 1 });
        return true;
      } else {
        return false;
      }
    },

    remaining(key: string, nowMs: number): number {
      let state = map.get(key);
      if (!state) {
        const windowStart = nowMs - (nowMs % windowMs);
        state = { windowStart, remaining: limit };
        map.set(key, state);
      }

      const { windowStart, remaining } = state;

      if (nowMs - windowStart >= windowMs) {
        const newWindowStart = nowMs - (nowMs % windowMs);
        map.set(key, { windowStart: newWindowStart, remaining: limit });
        return limit;
      }

      return remaining;
    },

    reset(key: string): void {
      map.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
