```ts
type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class EventEmitterImplementation {
  private _listeners = new Map<string, { listener: Listener; once: boolean }[]>();

  on(event: string, listener: Listener): number {
    const listeners = this._getListeners(event);
    listeners.push({ listener, once: false });
    return listeners.length;
  }

  once(event: string, listener: Listener): number {
    const listeners = this._getListeners(event);
    listeners.push({ listener, once: true });
    return listeners.length;
  }

  off(event: string, listener: Listener): boolean {
    const listeners = this._getListeners(event);
    const index = listeners.findIndex(l => l.listener === listener);
    if (index !== -1) {
      listeners.splice(index, 1);
      return true;
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this._getListeners(event);
    const results: unknown[] = [];
    for (let i = 0; i < listeners.length; ) {
      const listener = listeners[i];
      results.push(listener.listener(payload));
      if (listener.once) {
        listeners.splice(i, 1);
      } else {
        i++;
      }
    }
    return results;
  }

  listenerCount(event: string): number {
    return this._getListeners(event).length;
  }

  private _getListeners(event: string): { listener: Listener; once: boolean }[] {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    return this._listeners.get(event) as { listener: Listener; once: boolean }[];
