export function createRateLimiter() {
  const state = new Map<string, number[]>();

  return {
    allow(key: string, nowMs: number): boolean {
      const timestamps = state.get(key) || [];
      if (timestamps.length === 0) {
        state.set(key, [nowMs]);
        return true;
      }

      const earliest = timestamps[0];
      if (nowMs - earliest > 1000) {
        state.set(key, [nowMs]);
        return true;
      }

      const windowed = timestamps.filter(ts => ts >= nowMs - 1000);
      if (windowed.length >= 3) {
        return false;
      }

      state.set(key, [...timestamps, nowMs]);
      return true;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}
