type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

class EventEmitter {
  private regularListeners: Record<string, Listener[]> = {};
  private oneTimeListeners: Record<string, Listener[]> = {};

  on(event: string, listener: Listener): number {
    if (!this.regularListeners[event]) {
      this.regularListeners[event] = [];
    }
    this.regularListeners[event].push(listener);
    return this.regularListeners[event].length;
  }

  once(event: string, listener: Listener): number {
    if (!this.oneTimeListeners[event]) {
      this.oneTimeListeners[event] = [];
    }
    this.oneTimeListeners[event].push(listener);
    return this.oneTimeListeners[event].length;
  }

  off(event: string, listener: Listener): boolean {
    const regular = this.regularListeners[event] || [];
    const oneTime = this.oneTimeListeners[event] || [];

    for (let i = 0; i < regular.length; i++) {
      if (regular[i] === listener) {
        regular.splice(i, 1);
        return true;
      }
    }

    for (let i = 0; i < oneTime.length; i++) {
      if (oneTime[i] === listener) {
        oneTime.splice(i, 1);
        return true;
      }
    }

    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const regular = this.regularListeners[event] || [];
    const oneTime = this.oneTimeListeners[event] || [];
    const results: unknown[] = [];

    for (const listener of regular) {
      results.push(listener(payload));
    }

    for (let i = 0; i < oneTime.length; i++) {
      const listener = oneTime[i];
      results.push(listener(payload));
      this.oneTimeListeners[event].splice(i, 1);
      i--;
    }

    return results;
  }

  listenerCount(event: string): number {
    const regular = this.regularListeners[event] || [];
    const oneTime = this.oneTimeListeners[event] || [];
    return regular.length + oneTime.length;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter();
}
