export function createTodoApp(): TodoApp {
  const todos = new Map<number, Todo>();
  let nextId = 1;

  const addTodo = (text: string): Todo => {
    const todo: Todo = { id: nextId, text, completed: false };
    todos.set(nextId, todo);
    nextId++;
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => todos.get(id);

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) todo.completed = !todo.completed;
  };

  const deleteTodo = (id: number): boolean => {
    if (todos.has(id)) {
      todos.delete(id);
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => Array.from(todos.values());

  const listCompleted = (): Todo[] => Array.from(todos.values()).filter(todo => todo.completed);

  const listPending = (): Todo[] => Array.from(todos.values()).filter(todo => !todo.completed);

  const clearCompleted = (): void => {
    const pendingTodos = new Map<number, Todo>();
    todos.forEach((todo, id) => {
      if (!todo.completed) pendingTodos.set(id, todo);
    });
    todos.clear();
    todos.set(...pendingTodos);
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
