export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const expiration = nowMs + (ttlMs ?? 1000);
      cache.set(key, { value, expiresAt: expiration });
    },
    get(key: string, nowMs: number) {
      const entry = cache.get(key);
      return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    },
    has(key: string, nowMs: number) {
      const entry = cache.get(key);
      return entry && nowMs < entry.expiresAt;
    },
    delete(key: string) {
      return cache.delete(key);
    },
    size(nowMs: number) {
      let count = 0;
      for (const [key, entry] of cache) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    }
  };
}

```typescript
interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  class TtlCacheImpl implements TtlCache {
    private cache = new Map<string, { value: unknown; expiresAt: number }>();

    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000) {
      const expiresAt = nowMs + ttlMs;
      this.cache.set(key, { value, expiresAt });
    }

    get(key: string, nowMs: number): unknown {
      const entry = this.cache.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        this.cache.delete(key);
        return undefined;
      }
      return entry.value;
    }

    has(key: string, nowMs: number): boolean {
      const entry = this.cache.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        this.cache.delete(key);
        return false;
      }
      return true;
    }

    delete(key: string): boolean {
      return this.cache.delete(key);
    }

    size(nowMs: number): number {
      return Array.from(this.cache).reduce(
        (count, [key, entry]) => count + (nowMs < entry.expiresAt ? 1 : 0),
        0
      );
    }

    clear(): void {
      this.cache.clear();
    }
  }

  return new TtlCacheImpl();
}
