class EventEmitterImpl implements EventEmitter {
  private eventMap: Map<string, Array<{ listener: Listener, once: boolean }>> = new Map();

  on(event: string, listener: Listener): number {
    const listeners = this.eventMap.get(event) || [];
    listeners.push({ listener, once: false });
    this.eventMap.set(event, listeners);
    return listeners.length;
  }

  once(event: string, listener: Listener): number {
    const listeners = this.eventMap.get(event) || [];
    listeners.push({ listener, once: true });
    this.eventMap.set(event, listeners);
    return listeners.length;
  }

  off(event: string, listener: Listener): boolean {
    const listeners = this.eventMap.get(event) || [];
    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i].listener === listener) {
        listeners.splice(i, 1);
        this.eventMap.set(event, listeners);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this.eventMap.get(event) || [];
    const toProcess = [...listeners];
    const results: unknown[] = [];

    for (const listener of toProcess) {
      const result = listener.listener(payload);
      results.push(result);
      if (listener.once) {
        const index = listeners.indexOf(listener);
        if (index !== -1) {
          listeners.splice(index, 1);
        }
      }
    }

    return results;
  }

  listenerCount(event: string): number {
    const listeners = this.eventMap.get(event) || [];
    return listeners.length;
  }
