export function createRateLimiter() {
  const store = new Map<string, { count: number; end: number }>();

  return {
    check(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      let { count, end } = entry || { count: 0, end: 0 };

      if (nowMs >= end) {
        // Window has ended, start new one
        end = nowMs + 1000;
        count = 1;
      } else {
        if (count >= 3) {
          return false;
        }
        count++;
      }

      store.set(key, { count, end });
      return true;
    },
    reset(key: string): void {
      store.delete(key);
    }
  };
}
