  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000) {
      const expiresAt = nowMs + ttlMs;
      cache.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number) {
      const entry = cache.get(key);
      if (entry && entry.expiresAt > nowMs) {
        return entry.value;
      }
      return undefined;
    },
    has(key: string, nowMs: number) {
      const entry = cache.get(key);
      return !!entry && entry.expiresAt > nowMs;
    },
    delete(key: string) {
      const entry = cache.get(key);
      if (entry) {
        cache.delete(key);
        return true;
      }
      return false;
    },
    size(nowMs: number) {
      let count = 0;
      for (const [_, entry] of cache.entries()) {
        if (entry.expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    }
