  listCompleted: () => Array<{ id: number; text: string; completed: boolean }>;
  listPending: () => Array<{ id: number; text: string; completed: boolean }>;
  clearCompleted: () => void;
} {
  let todoIdCounter = 1;

  const todoStore: Array<{ id: number; text: string; completed: boolean }> = [];

  function getNextId(): number {
    return todoIdCounter++;
  }

  const addTodo = (text: string): { id: number; text: string; completed: boolean } => {
    const newTodo = { 
      id: getNextId(), 
      text, 
      completed: false 
    };
    todoStore.push(newTodo);
    return newTodo;
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined => {
    for (const todo of todoStore) {
      if (todo.id === id) return todo;
    }
    return undefined;
  };

  const toggleTodo = (id: number) => {
    const todoIndex = todoStore.findIndex(t => t.id === id);
    if (todoIndex === -1) return;
    todoStore[todoIndex].completed = !todoStore[todoIndex].completed;
  };

  const deleteTodo = (id: number): boolean => {
    const todoIndex = todoStore.findIndex(t => t.id === id);
    if (todoIndex === -1) return false;
    todoStore.splice(todoIndex, 1);
    return true;
  };

  const listTodos = (): Array<{ id: number; text: string; completed: boolean }> => {
    return [...todoStore];
  };

  const listCompleted = (): Array<{ id: number; text: string; completed: boolean }> => {
    return todoStore.filter(t => t.completed);
  };

  const listPending = (): Array<{ id: number; text: string; completed: boolean }> => {
    return todoStore.filter(t => !t.completed);
  };

  const clearCompleted = () => {
    todoStore = todoStore.filter(t => !t.completed);
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
