    const index = this.todos.findIndex(t => t.id === id);
    this.todos[index].completed = !this.todos[index].completed;
  },
  deleteTodo(id: number): boolean {
    const todoToDelete = this.getTodo(id);
    if (!todoToDelete) return false;
    const todosCopy = [...this.todos];
    todosCopy.splice(todosCopy.indexOf(todoToDelete), 1);
    return true;
  },
  listTodos(): Array<{ id: number; text: string; completed: boolean }> {
    return this.todos;
  },
  listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
