type Listener<T = void> = (...args: any[]) => T;

interface EventEmitter {
  on(event: string, listener: Listener): EventEmitter;
  once(event: string, listener: Listener): EventEmitter;
  off(event: string, listener: Listener): EventEmitter;
  emit(event: string, ...args: any[]): any[];
}

function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<Listener>>();
  const onceListeners = new Map<string, Array<Listener>>();

  return {
    on(event: string, listener: Listener): EventEmitter {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push(listener);
      return this;
    },

    once(event: string, listener: Listener): EventEmitter {
      const wrappedListener = (...args: any[]) => {
        const result = listener(...args);
        const list = onceListeners.get(event);
        if (list) {
          const idx = list.indexOf(wrappedListener);
          if (idx !== -1) {
            list.splice(idx, 1);
          }
        }
        return result;
      };

      if (!onceListeners.has(event)) {
        onceListeners.set(event, []);
      }
      onceListeners.get(event)!.push(wrappedListener);
      return this;
    },

    off(event: string, listener: Listener): EventEmitter {
      const list = listeners.get(event);
      if (list) {
        const idx = list.indexOf(listener);
        if (idx !== -1) {
          list.splice(idx, 1);
        }
      }

      const onceList = onceListeners.get(event);
      if (onceList) {
        const idx = onceList.indexOf(listener);
        if (idx !== -1) {
          onceList.splice(idx, 1);
        }
      }

      return this;
    },

    emit(event: string, ...args: any[]): any[] {
      const results: any[] = [];
      const list = listeners.get(event);
      if (list) {
        for (const listener of list) {
          results.push(listener(...args));
        }
      }

      const onceList = onceListeners.get(event);
      if (onceList) {
        for (const listener of onceList) {
          results.push(listener(...args));
        }
        onceListeners.delete(event);
      }

      return results;
    }
  };
}

export { createEventEmitter };
