interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  let todos: Todo[] = []
  let nextId: number = 1

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId,
        text,
        completed: false
      }
      todos = [...todos, todo]
      nextId++
      return todo
    },

    getTodo(id: number): Todo | undefined {
      for (const todo of todos) {
        if (todo.id === id) {
          return todo
        }
      }
      return undefined
    },

    toggleTodo(id: number): void {
      for (const todo of todos) {
        if (todo.id === id) {
          todo.completed = !todo.completed
          break
        }
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(todo => todo.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
        return true
      }
      return false
    },

    listTodos(): Todo[] {
      return [...todos]
    },

    listCompleted(): Todo[] {
      const result: Todo[] = []
      for (const todo of todos) {
        if (todo.completed) {
          result.push(todo)
        }
      }
      return result
    },

    listPending(): Todo[] {
      const result: Todo[] = []
      for (const todo of todos) {
        if (!todo.completed) {
          result.push(todo)
        }
      }
      return result
    },

    clearCompleted(): void {
      const remaining: Todo[] = []
      for (const todo of todos) {
        if (!todo.completed) {
          remaining.push(todo)
        }
      }
      todos = remaining
    }
  }
}
