interface CacheEntry {
  value: unknown
  expiresAt: number
}

export function createTtlCache() {
  const entries = new Map<string, CacheEntry>()
  const defaultTtlMs = 1000

  return {
    set(
      key: string,
      value: unknown,
      nowMs: number,
      ttlMs?: number
    ): void {
      entries.set(key, {
        value,
        expiresAt: nowMs + (ttlMs ?? defaultTtlMs),
      })
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        return false
      }
      return true
    },

    delete(key: string): boolean {
      if (entries.has(key)) {
        entries.delete(key)
        return true
      }
      return false
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of entries.values()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      entries.clear()
    },
  }
}
