    this.currentValue += n;
    return this;
  }

  subtract(n: number): Calculator {
    this.currentValue -= n;
    return this;
  }

  multiply(n: number): Calculator {
    this.currentValue *= n;
    return this;
  }

  divide(n: number): Calculator {
    if (n === 0) {
      return this as Calculator;
    }
    this.currentValue /= n;
    return this;
  }

  clear(): Calculator {
    this.currentValue = 0;
    return this;
  }

  result(): number {
    return this.currentValue;
  }

  memoryStore(): Calculator {
    this.memory = this.currentValue;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }

  memoryAdd(): Calculator {
    this.memory += this.currentValue;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new Calculator();
