interface EventCallback {
  listener: (payload: unknown) => unknown;
  once: boolean;
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

interface EventsMap {
  [event: string]: EventCallback[];
}

class EventEmitterImpl implements EventEmitter {
  private listeners: EventsMap;

  constructor() {
    this.listeners = {};
  }

  on(event: string, listener: Listener): number {
    const count = (this.listeners[event] || []).length + 1;

    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }

    const entry: EventCallback = {
      listener,
      once: false,
    };

    this.listeners[event].push(entry);

    return count;
  }

  once(event: string, listener: Listener): number {
    const onResult = this.on(event, listener as (payload: unknown) => unknown);

    const index = -1 !== (this.listeners[event] as EventCallback[]).findIndex(entry => entry.listener === listener && !entry.once);

    if (-1 !== index) {
      ;(this.listeners[event] as EventCallback[])[index].once = true;
    }

    return onResult;
  }

  off(event: string, listener: Listener): boolean {
    const list = this.listeners[event];

    if (!list || list.length === 0) {
      return false;
    }

    const idx = list.findIndex(entry => entry.listener === listener && !entry.once);

    if (-1 !== idx) {
      const removedEntry = list[idx];
      list.splice(idx, 1);

      return true;
    }

    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const results: unknown[] = [];

    if (!(event in this.listeners || !!this.listeners[event])) {
      return results;
    }

    const listenerList = this.listeners[event];

    for (const entry of listenerList) {
      if (!entry.once) {
        // Execute the listener once
        result = entry.listener(payload);
        results.push(result);

        // Once we're done firing all listeners, handle removal
        const hasOnce = list.some(entry => !entry.once);

        // After emit, remove any remaining one-time listeners that weren't already fired
      }
    }

    return results;
  }

  listenerCount(event: string): number {
    const count = (this.listeners[event] || []).filter(c => c.listener !== null).length;
    return count;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitterImpl();
}
