return {
    on(event: PropertyKey, listener: (...args: unknown[]) => unknown) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const list = listeners.get(event)!;
    list.push({ fn: listener, isOneTime: false });
  },

  once(event: PropertyKey, listener: (...args: unknown[]) => unknown) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const list = listeners.get(event)!;
    list.push({ fn: listener, isOneTime: true });
  },

  off(event: PropertyKey, listener: (...args: unknown[]) => unknown | null) {
    const list = listeners.get(event);
    if (!list) return;
    const newListenersArray: Array<{ fn: (...args: unknown[]) => unknown; isOneTime: boolean }> = [];

    for (const entry of list) {
      let removeMe = false;
      if (listener !== null && listener !== undefined) {
        removeMe = entry.fn === listener;
      }

      if (!removeMe) {
        newListenersArray.push(entry);
      }
    }

    listeners.set(event, newListenersArray);
  },

  emit(event: PropertyKey, ...args: unknown[]) {
    const listeners = listeners.get(event);

    if (!listeners) return [];

    const results: unknown[] = [];

    for (const entry of listeners) {
      try {
        let result;
        if (entry.isOneTime) {
          result = entry.fn(...args);
          if (!listeners.get(event)) { break;}
        } else {
          result = entry.fn.apply(this, args);
        }

        results.push(result !== undefined ? result : true);
      } catch (err) {
        console.error('Error in listener', err);
      }
    }

    return results;
  },
