export function createCalculator() {
  let currentValue: number = 0;
  let memoryValue: number = 0;

  const calculator = {
    add: (n: number) => {
      currentValue += n;
      return calculator;
    },
    subtract: (n: number) => {
      currentValue -= n;
      return calculator;
    },
    multiply: (n: number) => {
      currentValue *= n;
      return calculator;
    },
    divide: (n: number) => {
      if (n === 0) {
        throw new Error("Cannot divide by zero");
      }
      currentValue /= n;
      return calculator;
    },
    clear: () => {
      currentValue = 0;
      return calculator;
    },
    result: () => currentValue,
    memoryStore: () => {
      memoryValue = currentValue;
      return calculator;
    },
    memoryAdd: () => {
      memoryValue += currentValue;
      return calculator;
    },
    memoryClear: () => {
      memoryValue = 0;
      return calculator;
    },
    memoryRecall: () => memoryValue
  };

  return calculator;
