export type RateLimiterKey = string

interface RateLimiterState {
  count: number
  windowEndMs: number
}

export const createRateLimiter = (): {
  check: (key: string, nowMs: number) => boolean
  reset: (key: string) => void
} => {
  const states = new Map<string, RateLimiterState>()
  const WINDOW_SIZE_MS = 1000
  const MAX_REQUESTS = 3

  return {
    check: (key: string, nowMs: number): boolean => {
      let state = states.get(key)

      if (!state) {
        state = { count: 1, windowEndMs: nowMs + WINDOW_SIZE_MS }
        states.set(key, state)
        return true
      }

      const windowExpired = nowMs >= state.windowEndMs

      if (windowExpired) {
        state.count = 1
        state.windowEndMs = nowMs + WINDOW_SIZE_MS
        states.set(key, state)
        return true
      }

      state.count += 1

      if (state.count <= MAX_REQUESTS) {
        return true
      } else {
        return false
      }
    },

    reset: (key: string): void => {
      states.delete(key)
    }
  }
}
