```typescript
/**
 * TypeScript module implementing a flexible and robust EventEmitter
 * with comprehensive features for event-based communication.
 *
 * - Support for `on`, `once`, `off`, `emit` and listener management.
 * - Allows event listeners with payloads.
 * - Listeners are called in registration order.
 * - Duplicate listeners are supported and are individually managed.
 * - `once` listeners are invoked only once and then automatically removed.
 * - Return values from listener invocations are captured and collected.
 * - Exports `createEventEmitter` function returning the emitter instance.
 */

export interface Listener {
  (payload: unknown): unknown;
}

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

/**
 * Creates a new EventEmitter instance with full lifecycle and management for listeners.
 * @returns {EventEmitter} - A configured EventEmitter instance.
 */
export function createEventEmitter(): EventEmitter {
  const emitter: Partial<EventEmitter> = {
    listeners: new Map<string, Listener[]>(),
    on(event: string, listener: Listener): number {
      if (!this.listeners.has(event)) {
        this.listeners.set(event, []);
      }
      this.listeners.get(event)!.push(listener);
      return this.listenerCount(event);
    },
    once(event: string, listener: Listener): number {
      const removeOnCall = (...args: unknown[]) => {
        this.off(event, removeOnCall);
        return listener.apply(null, args || []);
      };
      return this.on(event, removeOnCall);
    },
    off(event: string, listener: Listener): boolean {
      if (!this.listeners.has(event)) return false;
      const idx = this.listeners.get(event)!.findIndex(fn => fn === listener);
      if (idx !== -1) {
        this.listeners.get(event)!.splice(idx, 1);
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      if (!this.listeners.has(event) || this.listeners.get(event)!.length === 0) return [];
      return this.listeners.get(event)!.map(listener => listener(payload || undefined));
    },
    listenerCount(event: string): number {
      return this.listeners.get(event)?.length ?? 0;
    },
  };
  return emitter as EventEmitter;
}
