```typescript
/**
 * Creates a rate limiter that constrains the number of requests per key using sliding windows.
 *
 * Implementation notes:
 * - Uses a fixed policy of 3 requests per 1000ms window (1000ms sliding). The window does NOT "slide" forward on
 *   every request, but uses an explicit reference timestamp that advances from each allow() or when reset() is called.
 * - Each key is independent.
 * - The window behavior is:
 *   - The next allowable timestamp (`nextAllowTimestamp`) begins at the window start time.
 *   - Each `allow()` decrements the remaining counter at that window. When the counter falls to 0, `nextAllowTimestamp`
 *     advances forward by the fixed policy window (1000ms) so the window is fresh for the next set of 3 requests.
 * - `reset()` clears the state for a specific key.
 * - Deterministic timestamping uses user-provided references via `nowMs` to allow reproducible behavior.
 *
 * Export: `createRateLimiter`
 */
export function createRateLimiter() {
  type KeyState = {
    // Unix millisecond timestamp of when the current fixed-policied window (start) begins.
    // The next allowable timestamp is `nextAllowTimestamp`. This timestamp advances on request consumption and on reset.
    windowStartMs: number;
    // Next allowable (non-inclusive) timestamp where a request may be allowed. When this reaches the current or newer
    // `currentNowMs`, the window will advance by the policy's window duration.
    nextAllowTimestamp: number;
    // Remaining number of allowed requests available in the current window.
    remaining: number;
    // The window duration in milliseconds that represents each fixed-policied interval.
    windowDurationMs: number;
  };

  const states = new Map<string, KeyState>();

  /**
   * Allow a request for the given key, returning true if allowed.
   * @param key - The key which will have its quota tracked independently.
   * @param currentNowMs - Deterministic current time in ms provided by the caller.
   * @returns `true` if the request is allowed (rate limit permits), `false` otherwise.
   */
  function allow(key: string, currentNowMs: number): boolean {
    const policyWindowDurationMs = 1000;
    const allowedPerWindow = 3;

    let state = states.get(key);
    if (!state) {
      state = {
        windowStartMs: currentNowMs,
        // The fixed window "sliding" starts immediately from `currentNowMs`.
        nextAllowTimestamp: currentNowMs,
        remaining: allowedPerWindow,
        windowDurationMs: policyWindowDurationMs,
      };
      states.set(key, state);
    }

    // Advance the window if necessary. `nextAllowTimestamp` is the exact timestamp where one extra request is allowed.
    if (state.nextAllowTimestamp <= currentNowMs) {
      // Advance to a fresh policy window: start a new window, and refill the remaining count.
      state.windowStartMs = currentNowMs;
      state.nextAllowTimestamp = currentNowMs;
      state.remaining = allowedPerWindow;
    }

    if (state.remaining > 0) {
      // Allow the operation.
      state.nextAllowTimestamp += state.windowDurationMs;
