  function reset(key: string): void {
    states.delete(key);
  }

  /**
   * For testing, clear all state.
   */
  function clearAll(): void {
    states.clear();
  }

  return {
    allow,
    reset,
    // Exported for testing.
    _clearAll: clearAll,
  };
