export function createTtlCache(): TtlCache {
  const defaultTtl = 1000; // 1000ms default TTL

  interface Entry {
    value: unknown;
    expiresAt: number;
  }

  const entries = new Map<string, Entry>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = defaultTtl): void {
      const expiresAt = nowMs + (ttlMs ?? defaultTtl);
      entries.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return entries.delete(key);
    },

    size(nowMs: number): number {
      const validEntries = Array.from(entries.entries()).filter(
        ([_, { expiresAt }]) => nowMs < expiresAt
      );
      return validEntries.length;
    },

    clear(): void {
      entries.clear();
    },
  };
}
