export function createEventEmitter() {
  const listeners = new Map<
    string,
    Array<{ fn: (...args: any[]) => any; once: boolean }>
  >();

  function on(event: string, fn: (...args: any[]) => any): void {
    const arr = listeners.get(event) ?? [];
    arr.push({ fn, once: false });
    listeners.set(event, arr);
  }

  function once(event: string, fn: (...args: any[]) => any): void {
    const arr = listeners.get(event) ?? [];
    arr.push({ fn, once: true });
    listeners.set(event, arr);
  }

  function off(event: string, fn: (...args: any[]) => any): void {
    const arr = listeners.get(event);
    if (!arr) return;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === fn) {
        arr.splice(i, 1);
        break;
      }
    }
    if (arr.length === 0) {
      listeners.delete(event);
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const arr = listeners.get(event);
    if (!arr) return [];
    const results: any[] = [];
    const toCall = arr.slice(); // copy to preserve order while removing
    for (const listener of toCall) {
      const result = listener.fn(...args);
      results.push(result);
      if (listener.once) {
        const idx = arr.indexOf(listener);
        if (idx !== -1) {
          arr.splice(idx, 1);
        }
      }
    }
    if (arr.length === 0) {
      listeners.delete(event);
    }
    return results;
  }

  return { on, once, off, emit };
}
