export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { count: number; windowStart: number }>();

  const allow = (key: string, nowMs: number): boolean => {
    const state = store.get(key);
    if (state && nowMs - state.windowStart < windowMs) {
      if (state.count < limit) {
        state.count++;
        return true;
      }
      return false;
    }
    // start new window
    store.set(key, { count: 1, windowStart: nowMs });
    return true;
  };

  const remaining = (key: string, nowMs: number): number => {
    const state = store.get(key);
    if (state && nowMs - state.windowStart < windowMs) {
      return Math.max(limit - state.count, 0);
    }
    return limit;
  };

  const reset = (key: string): void => {
    store.delete(key);
  };

  return { allow, remaining, reset };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
}

