        if (arr[i].fn === fn) {
          arr.splice(i, 1);
          break;
        }
      }
      if (arr.length === 0) {
        listenerMap.delete(event);
      }
    },
    emit(event: string, ...args: any[]): any[] {
      const arr = listenerMap.get(event);
      if (!arr) return [];
      const results: any[] = [];
      for (let i = 0; i < arr.length; ) {
        const entry = arr[i];
        results.push(entry.fn(...args));
        if (entry.once) {
          arr.splice(i, 1);
        } else {
          i++;
        }
      }
      if (arr.length === 0) {
        listenerMap.delete(event);
      }
      return results;
    },
  };
}

