export function createEventEmitter() {
  const listeners = new Map<string, Array<{ fn: (...args: any[]) => any, once: boolean }>>();

  function on(event: string, fn: (...args: any[]) => any) {
    if (!listeners.has(event)) listeners.set(event, []);
    listeners.get(event)!.push({ fn, once: false });
    return this;
  }

  function once(event: string, fn: (...args: any[]) => any) {
    if (!listeners.has(event)) listeners.set(event, []);
    listeners.get(event)!.push({ fn, once: true });
    return this;
  }

  function off(event: string, fn?: (...args: any[]) => any) {
    const evListeners = listeners.get(event);
    if (!evListeners) return this;
    if (fn === undefined) {
      listeners.delete(event);
      return this;
    }
    const index = evListeners.findIndex(l => l.fn === fn);
    if (index !== -1) {
      const filtered = [...evListeners];
      filtered.splice(index, 1);
      listeners.set(event, filtered);
    }
    return this;
  }

  function emit(event: string, ...args: any[]): any[] {
    const evListeners = listeners.get(event);
    if (!evListeners) return [];
    const results: any[] = [];
    const remaining: Array<{ fn: (...args: any[]) => any, once: boolean }> = [];
    for (const listener of evListeners) {
      results.push(listener.fn(...args));
      if (!listener.once) {
        remaining.push(listener);
      }
    }
    if (remaining.length > 0) {
      listeners.set(event, remaining);
    }
    return results;
  }

  return { on, once, off, emit };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>()
  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) listeners.set(event, [])
      const arr = listeners.get(event)!
      arr.push({ listener, once: false })
      return arr.length
    },
    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) listeners.set(event, [])
      const arr = listeners.get(event)!
      arr.push({ listener, once: true })
      return arr.length
    },
    off(event: string, listener: Listener): boolean {
      const arr = listeners.get(event)
      if (!arr) return false
      const idx = arr.findIndex(item => item.listener === listener)
      if (idx === -1) return false
      arr.splice(idx, 1)
      if (arr.length === 0) listeners.delete(event)
      return true
    },
    emit(event: string, payload: unknown): unknown[] {
      const arr = listeners.get(event)
      if (!arr) return []
      const results: unknown[] = []
      for (const item of [...arr]) {
        results.push(item.listener(payload))
        if (item.once) {
          const idx = arr.indexOf(item)
          if (idx !== -1) arr.splice(idx, 1)
        }
      }
      return results
    },
    listenerCount(event: string): number {
      return listeners.get(event)?.length ?? 0
    }
  } as EventEmitter
}

export function createRateLimiter(nowMs: () => number) {
  const map = new Map<string, { start: number; count: number }>();
  return {
    allow(key: string): boolean {
      const now = nowMs();
      let state = map.get(key);
      if (!state) {
        map.set(key, { start: now, count: 1 });
        return true;
      }
      if (now - state.start >= 1000) {
        state.start = now;
        state.count = 1;
        return true;
      }
      if (state.count < 3) {
        state.count++;
        return true;
      }
      return false;
    },
    reset(key: string): void {
      map.delete(key);
    }
  };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { count: number; start: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) {
        store.set(key, { count: 1, start: nowMs });
        return true;
      }
      if (nowMs - entry.start >= windowMs) {
        entry.count = 1;
        entry.start = nowMs;
        return true;
      }
      if (entry.count < limit) {
        entry.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const entry = store.get(key);
      if (!entry) return limit;
      if (nowMs - entry.start >= windowMs) return limit;
      return Math.max(limit - entry.count, 0);
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

